    [('user=None', '换 key 且无 fallback 后,旧 cookie 的 /me 结果'), ('两步走', '先让所有实例认新 key,再切换签名 key'), ('BadTimeSignature', 'itsdangerous 令牌在只用新 key 校验时的错误')],
